// The hold's identity on both sides of the line: the Redis key and the
// Postgres mirror row are both keyed by it. Generated by the TokenGenerator
// port (TB-007), never by the domain.
export type HoldToken = string & { readonly __brand: "HoldToken" };

export function holdToken(value: string): HoldToken {
  return value as HoldToken; // brand cast — the only place a string becomes a token
}
